#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/file.h>

static const char format_text[]="DARC\nformat=1\nhash=sha256\nchunking=buzhash64\ncompression=lzh1\nparity=xor8+1\n";
static int mk(const char*r,const char*s){char*p=darc_path_join(r,s);if(!p)return -1;int z=darc_mkdir_p(p,0755);free(p);return z;}
int darc_repo_init(const char*path,const DarcConfig*cfg){struct stat st;if(!stat(path,&st)){DIR*d=opendir(path);if(!d)return -1;struct dirent*de;int nonempty=0;while((de=readdir(d)))if(strcmp(de->d_name,".")&&strcmp(de->d_name,"..")){nonempty=1;break;}closedir(d);if(nonempty){errno=EEXIST;return -1;}}else if(errno==ENOENT){if(darc_mkdir_p(path,0755))return -1;}else return -1;const char*dirs[]={"refs/snapshots","objects/sha256","index","parity","state","journal","tmp","locks"};for(size_t i=0;i<sizeof dirs/sizeof dirs[0];i++)if(mk(path,dirs[i]))return -1;char*p=darc_path_join(path,"FORMAT");if(!p)return -1;if(darc_atomic_write(p,format_text,sizeof(format_text)-1,0644)){free(p);return -1;}free(p);p=darc_path_join(path,"HEAD");if(!p)return -1;if(darc_atomic_write(p,"",0,0644)){free(p);return -1;}free(p);p=darc_path_join(path,"parity/CATALOG");if(!p)return -1;if(darc_atomic_write(p,"DARCPAR1\n",9,0644)){free(p);return -1;}free(p);if(cfg&&darc_config_write_repo_defaults(path,cfg))return -1;return darc_index_rebuild(path);}
int darc_repo_check(const char*repo){char*p=darc_path_join(repo,"FORMAT");if(!p)return DARC_E_IO;DarcBuf b;if(darc_read_file(p,&b,4096)){free(p);return errno==ENOENT?DARC_E_REPO:DARC_E_IO;}free(p);int rc=DARC_OK;if(b.len!=sizeof(format_text)-1||memcmp(b.data,format_text,b.len)){if(b.len>=4&&!memcmp(b.data,"DARC",4))rc=DARC_E_UNSUPPORTED;else rc=DARC_E_REPO;}darc_buf_free(&b);return rc;}
char*darc_object_path(const char*repo,const DarcCid*cid){char h[65];darc_cid_hex(cid,h);char rel[128];snprintf(rel,sizeof rel,"objects/sha256/%.2s/%s",h,h+2);return darc_path_join(repo,rel);}
void darc_object_free(DarcObject*o){darc_buf_free(&o->payload);memset(o,0,sizeof*o);}
static int ensure_objdir(const char*repo,const DarcCid*cid){char h[65];darc_cid_hex(cid,h);char rel[64];snprintf(rel,sizeof rel,"objects/sha256/%.2s",h);return mk(repo,rel);}
int darc_object_store(const char*repo,uint8_t type,const uint8_t*payload,size_t len,const DarcConfig*cfg,DarcCid*cid,uint64_t*stored_payload_bytes,bool*is_new){darc_object_cid(type,payload,len,cid);char*path=darc_object_path(repo,cid);if(!path)return DARC_E_IO;struct stat st;if(!stat(path,&st)){DarcObject old;int r=darc_object_load(repo,cid,&old,1);if(r){free(path);return r;}int same=old.type==type&&old.payload.len==len&&!memcmp(old.payload.data,payload,len);darc_object_free(&old);free(path);if(!same)return DARC_E_CORRUPT;if(stored_payload_bytes)*stored_payload_bytes=0;if(is_new)*is_new=false;return 0;}if(errno!=ENOENT){free(path);return DARC_E_IO;}DarcBuf comp;darc_buf_init(&comp);const uint8_t*stored=payload;size_t slen=len;uint8_t codec=0;if(type==OBJ_CHUNK&&cfg&&cfg->compression_enabled&&len){if(!darc_lzh1_compress(payload,len,&comp)&&comp.len+cfg->min_savings<=len){stored=comp.data;slen=comp.len;codec=1;}}
 DarcBuf f;darc_buf_init(&f);if(darc_buf_put(&f,"DARCOBJ1",8)||darc_buf_u8(&f,type)||darc_buf_u8(&f,codec)||darc_buf_u16(&f,0)||darc_buf_u64(&f,(uint64_t)len)||darc_buf_u64(&f,(uint64_t)slen))goto oom;uint32_t hc=darc_crc32c(f.data+8,20);if(darc_buf_u32(&f,hc)||darc_buf_put(&f,stored,slen)||darc_buf_u32(&f,darc_crc32c(stored,slen)))goto oom;if(ensure_objdir(repo,cid))goto io;char*tmpdir=darc_path_join(repo,"tmp");if(!tmpdir)goto oom;char hex[65];darc_cid_hex(cid,hex);char*tmp=darc_path_join(tmpdir,hex);free(tmpdir);if(!tmp)goto oom;size_t tl=strlen(tmp);char*tmp2=darc_malloc(tl+32);if(!tmp2){free(tmp);goto oom;}snprintf(tmp2,tl+32,"%s.%ld.tmp",tmp,(long)getpid());free(tmp);int fd=open(tmp2,O_CREAT|O_EXCL|O_WRONLY|O_CLOEXEC,0644);if(fd<0){free(tmp2);goto io;}if(getenv("DARC_TEST_SHORT_OBJECT_WRITE")){size_t z=f.len>1?f.len/2:f.len;if(z&&(write(fd,f.data,z)!=(ssize_t)z)){int e=errno;close(fd);unlink(tmp2);free(tmp2);errno=e;goto io;}errno=EIO;close(fd);unlink(tmp2);free(tmp2);goto io;}if(darc_write_all(fd,f.data,f.len)||(getenv("DARC_TEST_FAIL_OBJECT_FSYNC")?(errno=EIO,1):darc_fsync_fd(fd))||close(fd)){int e=errno;close(fd);unlink(tmp2);free(tmp2);errno=e;goto io;}darc_checkpoint("object_before_publish");if(getenv("DARC_TEST_FAIL_OBJECT_RENAME")){errno=EIO;unlink(tmp2);free(tmp2);goto io;}if(darc_rename_path(tmp2,path)){if(errno==EEXIST){unlink(tmp2);}else{int e=errno;unlink(tmp2);free(tmp2);errno=e;goto io;}}free(tmp2);{char*dir=darc_dirname_dup(path);if(!dir){errno=ENOMEM;goto io;}int dfd=open(dir,O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(dfd<0){free(dir);goto io;}if(darc_fsync_fd(dfd)){int e=errno;close(dfd);free(dir);errno=e;goto io;}if(close(dfd)){int e=errno;free(dir);errno=e;goto io;}free(dir);}darc_checkpoint("object_after_publish");free(path);darc_buf_free(&f);darc_buf_free(&comp);if(stored_payload_bytes)*stored_payload_bytes=(uint64_t)slen;if(is_new)*is_new=true;return 0;
oom:errno=ENOMEM;io:free(path);darc_buf_free(&f);darc_buf_free(&comp);return DARC_E_IO;}
int darc_object_load(const char*repo,const DarcCid*cid,DarcObject*out,int verify_cid){memset(out,0,sizeof*out);char*p=darc_object_path(repo,cid);if(!p)return DARC_E_IO;DarcBuf f;if(darc_read_file(p,&f,64u*1024u*1024u)){int e=errno;free(p);return e==ENOENT?DARC_E_CORRUPT:DARC_E_IO;}free(p);if(f.len<36||memcmp(f.data,"DARCOBJ1",8)){darc_buf_free(&f);return DARC_E_CORRUPT;}uint8_t type=f.data[8],codec=f.data[9];if(type<1||type>5||codec>1||darc_rd_u16(f.data+10)!=0){darc_buf_free(&f);return DARC_E_UNSUPPORTED;}uint64_t ul=darc_rd_u64(f.data+12),sl=darc_rd_u64(f.data+20);if(sl>SIZE_MAX||ul>SIZE_MAX||36u+(size_t)sl!=f.len||darc_rd_u32(f.data+28)!=darc_crc32c(f.data+8,20)){darc_buf_free(&f);return DARC_E_CORRUPT;}const uint8_t*sp=f.data+32;if(darc_rd_u32(sp+(size_t)sl)!=darc_crc32c(sp,(size_t)sl)){darc_buf_free(&f);return DARC_E_CORRUPT;}DarcBuf dec;if(codec==0){darc_buf_init(&dec);if(darc_buf_put(&dec,sp,(size_t)sl)){darc_buf_free(&f);return DARC_E_IO;}if(ul!=sl){darc_buf_free(&f);darc_buf_free(&dec);return DARC_E_CORRUPT;}}else if(darc_lzh1_decompress(sp,(size_t)sl,(size_t)ul,&dec)){darc_buf_free(&f);return DARC_E_CORRUPT;}if(verify_cid){DarcCid got;darc_object_cid(type,dec.data,dec.len,&got);if(!darc_cid_eq(&got,cid)){darc_buf_free(&dec);darc_buf_free(&f);return DARC_E_CORRUPT;}}if(type!=OBJ_CHUNK){if(dec.len<2){darc_buf_free(&dec);darc_buf_free(&f);return DARC_E_CORRUPT;}if(darc_rd_u16(dec.data)!=DARC_FORMAT_VERSION){darc_buf_free(&dec);darc_buf_free(&f);return DARC_E_UNSUPPORTED;}}out->type=type;out->codec=codec;out->uncomp_len=ul;out->stored_len=sl;out->payload=dec;darc_buf_free(&f);return 0;}
int darc_object_header(const char*path,DarcRhEnt*out){uint8_t h[32];int fd=open(path,O_RDONLY|O_CLOEXEC);if(fd<0)return -1;size_t o=0;while(o<32){ssize_t r=read(fd,h+o,32-o);if(r<0){if(errno==EINTR)continue;close(fd);return -1;}if(!r){close(fd);return -1;}o+=(size_t)r;}close(fd);if(memcmp(h,"DARCOBJ1",8)||darc_rd_u16(h+10)!=0||darc_rd_u32(h+28)!=darc_crc32c(h+8,20))return -1;out->type=h[8];out->codec=h[9];out->uncomp_len=darc_rd_u64(h+12);out->stored_len=darc_rd_u64(h+20);return 0;}
int darc_lock_acquire(const char*repo,int*fd_out){char*p=darc_path_join(repo,"locks/writer.lock");if(!p)return DARC_E_IO;int fd=open(p,O_CREAT|O_RDWR|O_CLOEXEC,0644);free(p);if(fd<0)return DARC_E_IO;if(flock(fd,LOCK_EX|LOCK_NB)){close(fd);return errno==EWOULDBLOCK?DARC_E_LOCKED:DARC_E_IO;}/* flock state is authoritative. Do not rewrite advisory metadata on every acquire: a healthy repair-capable verify must be byte+metadata idempotent. */*fd_out=fd;return 0;}
void darc_lock_release(const char*repo,int fd){(void)repo;if(fd>=0){(void)flock(fd,LOCK_UN);close(fd);}}
int darc_recover_journals(const char*repo){int lock=-1,rc=darc_lock_acquire(repo,&lock);if(rc)return rc;const char*dirs[]={"journal","tmp"};for(size_t di=0;di<2;di++){char*p=darc_path_join(repo,dirs[di]);if(!p){rc=DARC_E_IO;break;}DIR*d=opendir(p);if(!d){free(p);rc=DARC_E_IO;break;}struct dirent*de;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;char*q=darc_path_join(p,de->d_name);if(!q||darc_remove_tree(q)){free(q);rc=DARC_E_IO;break;}free(q);}closedir(d);free(p);if(rc)break;}darc_lock_release(repo,lock);return rc;}
